  "name": "gobbi",
  "private": true,
  "description": "Open-source ClaudeX tool — workflow orchestration and docs management for Claude Code",
  "workspaces": [
    "packages/*"
  ],
  "engines": {
    "node": ">=18.0.0"
  },
  "scripts": {
    "build": "npm run build --workspaces"
  },
  "devDependencies": {
    "@types/node": "^18",
    "typescript": "^5.8"
  },
  "license": "MIT",
  "author": "HahyeonJeon",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/HahyeonJeon/gobbi.git"
